const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net','').replace('@g.us','');

if (key.fromMe) return [];

const message = data.message || {};
const messageType = data.messageType || 'unknown';
let textContent = '';
if (messageType === 'conversation') textContent = message.conversation || '';
else if (messageType === 'extendedTextMessage') textContent = (message.extendedTextMessage||{}).text || '';
else if (messageType === 'audioMessage') textContent = '[رسالة صوتية]';
else textContent = message.conversation || message.text || '';

// Normalize
// تحويل "X أيام" الرقمي → (X-1) ليالي
textContent = textContent.replace(/(\d+)\s*(ايام|أيام|يوم)/g, (m, d) => {
  const nights = parseInt(d) - 1;
  return nights + ' ليالي';
});
textContent = textContent.replace(/اسبوعين|أسبوعين/g, '14 ليالي');
textContent = textContent.replace(/اسبوع|أسبوع/g, '7 ليالي');
textContent = textContent.replace(/عشر ايام|عشرة ايام|عشر أيام|عشرة أيام/g, '9 ليالي');
textContent = textContent.replace(/خمسة ايام|خمس ايام|خمسة أيام/g, '4 ليالي');
textContent = textContent.replace(/ستة ايام|ست ايام/g, '5 ليالي');

const MANAGER_PHONE = '380936582617';
const isManager = (phone === MANAGER_PHONE);
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const h = { 'apikey': KEY, 'Authorization': 'Bearer '+KEY, 'Content-Type': 'application/json' };

let isNew = false, lead = null;
try {
  const r = await this.helpers.httpRequest({ method:'GET', url:`${SB}/leads?phone=eq.${phone}&limit=1`, headers:h });
  if (r.length > 0) {
    lead = r[0];
    await this.helpers.httpRequest({ method:'PATCH', url:`${SB}/leads?phone=eq.${phone}`, headers:{...h,'Prefer':'return=minimal'}, body:{ last_contact: new Date().toISOString(), updated_at: new Date().toISOString() } });
  } else {
    isNew = true;
    if (!isManager) {
      const r2 = await this.helpers.httpRequest({ method:'POST', url:`${SB}/leads`, headers:{...h,'Prefer':'return=representation'}, body:{ phone, stage:'new', assigned_to:'bot', source:'direct', last_contact: new Date().toISOString() } });
      lead = r2[0] || null;
    }
  }
} catch(e) {}

if (!isManager) {
  try { await this.helpers.httpRequest({ method:'POST', url:`${SB}/conversations`, headers:{...h,'Prefer':'return=minimal'}, body:{ phone, role:'user', message:textContent } }); } catch(e) {}
}

// SESSION RESET: عند التحية → احذف التاريخ القديم ثم اجلب الحديث
const _greetingRx = /^(السلام|سلام|مرحبا|هلا|أهلا|ياهلا|صباح|مساء|هلو|hello|hi\b|جديد|بداية جديدة|new)/i;
const _isNewSession = _greetingRx.test(textContent.trim());
if (_isNewSession && phone) {
  // RESET LEAD DATA on greeting
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SB + '/leads?phone=eq.' + phone,
      headers: { ...h, Prefer: 'return=minimal' },
      body: {
        stage: 'new',
        destination: null,
        travel_dates: null,
        pax_adults: null,
        pax_children: null,
        children_ages: null,
        offer_sent: false,
        notes: null,
        next_followup: null,
        follow_up_count: 0,
        objection_type: null,
        needs_human: false,
        updated_at: new Date().toISOString()
      }
    });
    // Update local lead object too
    if (lead) {
      lead.stage = 'new';
      lead.destination = null;
      lead.travel_dates = null;
      lead.pax_adults = null;
      lead.pax_children = null;
      lead.children_ages = null;
      lead.offer_sent = false;
      lead.notes = null;
    }
  } catch(e) {}
  try {
    const _cutoff = new Date(Date.now() - 30000).toISOString();
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${SB}/conversations?phone=eq.${phone}&created_at=lt.${encodeURIComponent(_cutoff)}`,
      headers: h,
      returnFullResponse: true
    });
  } catch(e) {}
}

let chatHistory = '';
try {
  const msgs = await this.helpers.httpRequest({ method:'GET', url:`${SB}/conversations?phone=eq.${phone}&order=id.asc&limit=30`, headers:h });
  chatHistory = msgs.map(m => (m.role==='user'?'العميل':'ليلى')+': '+m.message).join('\n');
} catch(e) {}

let managerInstructions = '';
try {
  const inst = await this.helpers.httpRequest({ method:'GET', url:`${SB}/manager_instructions?active=eq.true&order=created_at.desc&limit=20`, headers:h });
  if (inst.length>0) managerInstructions = inst.map(i=>'- '+i.instruction).join('\n');
} catch(e) {}

let context = '';
if (isManager) context = 'هذا المدير أبو أمير — عامليه كمديرك.';
else if (isNew) context = 'عميل جديد — عرّفي نفسك "أنا ليلى من أركاديا للسياحة".';
else context = 'عميل سابق — لا تعرّفي نفسك.';
if (lead) {
  if (lead.name) context += ` اسمه: ${lead.name}.`;
  if (lead.destination) context += ` الوجهة: ${lead.destination}.`;
}

// كشف لغة العميل
const enWords = (textContent.match(/[a-zA-Z]{3,}/g) || []).length;
const totalWords = textContent.trim().split(/\s+/).length;
const customerLanguage = (enWords / Math.max(totalWords, 1)) > 0.5 ? 'en' : 'ar';

return [{ json: { phone, remoteJid, textContent, customerLanguage, isManager, isNew, lead, chatHistory, managerInstructions, context } }];

const prev = $input.first().json;
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const h = { 'apikey':KEY, 'Authorization':'Bearer '+KEY, 'Content-Type':'application/json', 'Prefer':'return=minimal' };
if (!prev.isManager) {
  try { await this.helpers.httpRequest({ method:'POST', url:`${SB}/conversations`, headers:h, body:{ phone:prev.phone, role:'assistant', message:prev.response } }); } catch(e) {}
}
return [{ json: prev }];

// ========================================
// Cancel Follow-up on Client Reply
// أول Code node في Laila V4 (بعد Webhook)
// يستخدم this.helpers.httpRequest (لا fetch)
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

const raw     = $input.first().json;
const msgData = raw.data || raw;

// Defensive fromMe detection
const incomingPhone = msgData?.key?.remoteJid?.replace('@s.whatsapp.net', '');
const isFromBot     = msgData?.key?.fromMe === true || msgData?.message?.fromMe === true;

if (!incomingPhone || isFromBot) {
  return $input.all();
}

try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/leads?phone=eq.${incomingPhone}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: {
      next_followup: null,
      last_contact: new Date().toISOString(),
    },
    json: true,
  });
} catch(e) {
  // لا نوقف الـ flow لو الـ patch فشل
  console.log(`[CANCEL-FU] patch failed: ${e.message}`);
}

return $input.all();

// ========================================
// Set Follow-up — Smart Detection
// بعد "Send WhatsApp" في Laila V4
// يستخدم this.helpers.httpRequest (لا fetch)
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

const ctx    = $input.first().json;
const phone  = ctx.phone
  || ctx.data?.key?.remoteJid?.replace('@s.whatsapp.net', '')
  || ctx.from;

const botMsg      = ctx.botMessage || ctx.finalResponse || ctx.message || '';
const destination = ctx.destination || ctx.context?.destination || null;
const name        = ctx.name || ctx.clientName || null;

if (!phone) return $input.all();

// Price Detection
const PRICE_PATTERNS = [
  /\$[\d,]+/, /USD\s*[\d,]+/i,
  /[\d,]{3,}\s*(دولار|ريال|درهم)/,
  /السعر[:\s]+/, /🥇|🥈|🥉/,
  /الاقتصادي|الفاخر|المتوسط/,
  /ليلة.*\$/,
];

const hasPriceSent = PRICE_PATTERNS.some(p => p.test(botMsg));
if (!hasPriceSent) return $input.all();

const nextFollowup = new Date(Date.now() + 30 * 60 * 1000).toISOString();

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/leads`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'resolution=merge-duplicates,return=representation',
    },
    body: {
      phone, name, destination,
      stage: 'quoted',
      follow_up_count: 0,
      next_followup: nextFollowup,
      paused: false,
      source: 'laila_v4',
    },
    json: true,
  });
} catch(e) {
  console.log(`[SET-FU] failed: ${e.message}`);
}

return $input.all();

// ═══════════════════════════════════════════════════════════════
// LAILA DECISION ENGINE v5 — النسخة النهائية المعتمدة
// أركاديا للسياحة — المساعدة الذكية
// الكود يتحكم 100% — لا AI يقرر
// ═══════════════════════════════════════════════════════════════

const prev = $input.first().json;
const phone = prev.phone;
const rawMsg = (prev.textContent || '').trim();
const chatHistory = prev.chatHistory || '';
const isManager = prev.isManager || false;
const lead = prev.lead || {};

// ─── CONFIG ──────────────────────────────────────────────
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const SB_KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const PE_URL = 'https://n8n.arcadia-tour.cloud/webhook/pricing-engine';
const TG_TOKEN = 'REDACTED_TELEGRAM_BOT_TOKEN';
const MGR_CHAT = '380936582617';
const SUPPORT = 'https://wa.me/380936582617';
const EXCHANGE_API = 'https://open.er-api.com/v6/latest/USD';
const sbH = { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' };

if (!phone || !rawMsg) return [];

// ─── DESTINATIONS ────────────────────────────────────────
const DESTS = {
  KZ: { name: 'كازاخستان 🇰🇿', pricing: true, defaultCity: 'Almaty', simCard: true },
  RU: { name: 'روسيا 🇷🇺', pricing: true, defaultCity: 'Moscow', simCard: false },
  PL: { name: 'بولندا 🇵🇱', pricing: false },
  UZ: { name: 'أوزبكستان 🇺🇿', pricing: false }
};

// ─── CURRENCY BY COUNTRY CODE ────────────────────────────
function getCurrencyByPhone(ph) {
  if (/^966/.test(ph)) return { code: 'SAR', label: 'ر.س' };
  if (/^965/.test(ph)) return { code: 'KWD', label: 'د.ك' };
  if (/^968/.test(ph)) return { code: 'OMR', label: 'ر.ع' };
  if (/^971/.test(ph)) return { code: 'AED', label: 'د.إ' };
  if (/^973/.test(ph)) return { code: 'BHD', label: 'د.ب' };
  if (/^974/.test(ph)) return { code: 'QAR', label: 'ر.ق' };
  if (/^964/.test(ph)) return { code: 'IQD', label: 'د.ع' };
  if (/^20/.test(ph)) return { code: 'EGP', label: 'ج.م' };
  if (/^962/.test(ph)) return { code: 'JOD', label: 'د.أ' };
  return null;
}

// ─── TEXT CLEANUP ─────────────────────────────────────────
function cleanText(t) {
  return (t || '')
    .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d).toString())
    .replace(/[\u0640]+/g, '')
    .replace(/(.)\1{2,}/g, '$1$1')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .trim();
}

const msg = cleanText(rawMsg);

// ─── WELCOME ─────────────────────────────────────────────
const WELCOME = 'يا هلا وسهلا! 👋\n\nأنا *ليلى*، المساعدة الذكية لشركة *أركاديا للسياحة* ✈️\n\nأقدر أساعدكم بعروض أسعار فورية لـ:\n🇰🇿 كازاخستان | 🇷🇺 روسيا | 🇵🇱 بولندا | 🇺🇿 أوزبكستان\n\n📝 *عشان أعطيكم أفضل عرض بسرعة ودقة، أرسلوا المعلومات التالية (ممكن في رسالة وحدة):*\n\n1️⃣ الوجهة والمدينة\n2️⃣ عدد البالغين + الأطفال وأعمارهم\n3️⃣ عدد الليالي\n4️⃣ تاريخ السفر تقريباً\n\n✅ مثال: "كازاخستان الماتي، شخصين، 7 ليالي، شهر 6"\n\n💡 أرسلوا *جديد* للبدء من جديد\n📞 للتواصل مع فريقنا المختص:\n👆 اضغطوا هنا: ' + SUPPORT;

// ─── HELPERS ─────────────────────────────────────────────
function reply(text) {
  return [{ json: { phone, remoteJid: prev.remoteJid, response: text, isManager: false } }];
}

function mgrReply(text) {
  return [{ json: { phone, remoteJid: prev.remoteJid, response: text, isManager: true } }];
}

async function updateLead(ph, patch) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH', url: SB + '/leads?phone=eq.' + ph,
      headers: { ...sbH, Prefer: 'return=representation' },
      body: { ...patch, updated_at: new Date().toISOString() }
    });
  } catch (e) { console.log('[DB] updateLead error:', e.message); }
}

async function notifyMgr(text) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + TG_TOKEN + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: MGR_CHAT, text, parse_mode: 'Markdown' }
    });
  } catch (e) { console.log('[TG] error:', e.message); }
}

async function callPE(body) {
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'POST', url: PE_URL,
        headers: { 'Content-Type': 'application/json' },
        body, json: true, timeout: 15000
      });
      if (r && (r.ok || r.noMore)) return r;
    } catch (e) {
      console.log('[PE] attempt ' + (attempt + 1) + ':', e.message);
      if (attempt === 0) continue;
    }
  }
  return { ok: false, error: true };
}

async function getExRate(cur) {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: EXCHANGE_API, timeout: 5000 });
    if (r && r.rates && r.rates[cur]) return r.rates[cur];
  } catch (e) {}
  const fb = { SAR: 3.75, KWD: 0.308, OMR: 0.385, AED: 3.673, BHD: 0.376, QAR: 3.64, EGP: 50.5, IQD: 1310, JOD: 0.709 };
  return fb[cur] || null;
}

// ─── ROOM CALCULATION ────────────────────────────────────
function calcRooms(adults, kids) {
  const total = adults + (kids || 0);
  if (total <= 2) return 'غرفة مزدوجة';
  if (total === 3) return 'مزدوجة + مفردة';
  if (total === 4) return '2 مزدوجة';
  if (total === 5) return '2 مزدوجة + مفردة';
  if (total === 6) return '3 مزدوجة';
  return Math.ceil(total / 2) + ' غرف';
}

// خيارات الغرف — ترجع null إذا ما في اختيار مطلوب
function getRoomOptions(adults, kids) {
  const total = adults + (kids || 0);
  // صيغة PE: { rooms: [{ occ: 'SGL'/'DBL'/'TRP', count: N }], label: '...' }
  const opts = {
    3: [
      { label: '1️⃣ غرفة مزدوجة + غرفة مفردة', config: { rooms: [{ occ: 'DBL', count: 1 }, { occ: 'SGL', count: 1 }], label: 'مزدوجة + مفردة' }, display: 'مزدوجة + مفردة' },
      { label: '2️⃣ غرفة ثلاثية',               config: { rooms: [{ occ: 'TRP', count: 1 }], label: 'ثلاثية' },                                   display: 'ثلاثية' }
    ],
    4: [
      { label: '1️⃣ غرفتان مزدوجتان',            config: { rooms: [{ occ: 'DBL', count: 2 }], label: '2 مزدوجة' },                                  display: '2 مزدوجة' },
      { label: '2️⃣ غرفة ثلاثية + غرفة مفردة',  config: { rooms: [{ occ: 'TRP', count: 1 }, { occ: 'SGL', count: 1 }], label: 'ثلاثية + مفردة' }, display: 'ثلاثية + مفردة' }
    ],
    5: [
      { label: '1️⃣ غرفتان مزدوجتان + مفردة',   config: { rooms: [{ occ: 'DBL', count: 2 }, { occ: 'SGL', count: 1 }], label: '2 مزدوجة + مفردة' }, display: '2 مزدوجة + مفردة' },
      { label: '2️⃣ مزدوجة + ثلاثية',            config: { rooms: [{ occ: 'DBL', count: 1 }, { occ: 'TRP', count: 1 }], label: 'مزدوجة + ثلاثية' }, display: 'مزدوجة + ثلاثية' }
    ],
    6: [
      { label: '1️⃣ 3 غرف مزدوجة',              config: { rooms: [{ occ: 'DBL', count: 3 }], label: '3 مزدوجة' },                                   display: '3 مزدوجة' },
      { label: '2️⃣ غرفتان ثلاثيتان',            config: { rooms: [{ occ: 'TRP', count: 2 }], label: '2 ثلاثية' },                                   display: '2 ثلاثية' }
    ],
    7: [
      { label: '1️⃣ ثلاثية + غرفتان مزدوجتان',  config: { rooms: [{ occ: 'TRP', count: 1 }, { occ: 'DBL', count: 2 }], label: 'ثلاثية + 2 مزدوجة' }, display: 'ثلاثية + 2 مزدوجة' },
      { label: '2️⃣ ثلاثيتان + مفردة',           config: { rooms: [{ occ: 'TRP', count: 2 }, { occ: 'SGL', count: 1 }], label: '2 ثلاثية + مفردة' },  display: '2 ثلاثية + مفردة' }
    ],
    8: [
      { label: '1️⃣ 4 غرف مزدوجة',              config: { rooms: [{ occ: 'DBL', count: 4 }], label: '4 مزدوجة' },                                   display: '4 مزدوجة' },
      { label: '2️⃣ ثلاثيتان + مزدوجة',          config: { rooms: [{ occ: 'TRP', count: 2 }, { occ: 'DBL', count: 1 }], label: '2 ثلاثية + مزدوجة' }, display: '2 ثلاثية + مزدوجة' }
    ],
    9: [
      { label: '1️⃣ 3 غرف ثلاثية',              config: { rooms: [{ occ: 'TRP', count: 3 }], label: '3 ثلاثية' },                                   display: '3 ثلاثية' },
      { label: '2️⃣ ثلاثيتان + مزدوجة + مفردة', config: { rooms: [{ occ: 'TRP', count: 2 }, { occ: 'DBL', count: 1 }, { occ: 'SGL', count: 1 }], label: '2 ثلاثية + مزدوجة + مفردة' }, display: '2 ثلاثية + مزدوجة + مفردة' }
    ],
    10: [
      { label: '1️⃣ ثلاثيتان + غرفتان مزدوجتان', config: { rooms: [{ occ: 'TRP', count: 2 }, { occ: 'DBL', count: 2 }], label: '2 ثلاثية + 2 مزدوجة' }, display: '2 ثلاثية + 2 مزدوجة' },
      { label: '2️⃣ 3 ثلاثية + مفردة',            config: { rooms: [{ occ: 'TRP', count: 3 }, { occ: 'SGL', count: 1 }], label: '3 ثلاثية + مفردة' },  display: '3 ثلاثية + مفردة' }
    ]
  };
  return opts[total] || null;
}

// ─── SMART ROOM MATCH — يطابق وصف العميل مع خيارات الغرف ──────────────
function matchRoomByDesc(msg, opts) {
  if (!opts || !msg) return null;
  const t = msg.trim();
  // رقمي صريح
  if (/^[1١]$/.test(t) || /^الأول|^الاول|^أول$|^اول$|^واحد$/.test(t)) return 0;
  if (/^[2٢]$/.test(t) || /^الثاني|^الثانى|^ثاني$|^ثانى$|^اثنين$/.test(t)) return 1;

  // كلمات وصفية — نبحث في label/display كل خيار
  const scores = opts.map((opt, i) => {
    const lbl = (opt.label + ' ' + opt.display).toLowerCase();
    let score = 0;
    if (/مزدوج|دبل|double/i.test(t) && /مزدوج/i.test(lbl)) score += 3;
    if (/ثلاثي|ثلاثية|triple/i.test(t) && /ثلاث/i.test(lbl)) score += 3;
    if (/مفرد|سينجل|single/i.test(t) && /مفرد/i.test(lbl)) score += 3;
    // عدد الغرف: "غرفتين" = 2 غرفة
    const roomCount = (opt.config?.rooms || []).reduce((s,r) => s + r.count, 0);
    if (/غرفتين|غرفتان|غرفتٌ|٢\s*غرف|2\s*غرف/.test(t) && roomCount === 2) score += 2;
    if (/غرفة واحدة|غرفه واحدة|غرفة وحدة|١\s*غرف|1\s*غرف/.test(t) && roomCount === 1) score += 2;
    if (/ثلاث\s*غرف|3\s*غرف|٣\s*غرف/.test(t) && roomCount === 3) score += 2;
    if (/أربع\s*غرف|4\s*غرف|٤\s*غرف/.test(t) && roomCount === 4) score += 2;
    return { score, i };
  });
  const best = scores.sort((a,b) => b.score - a.score)[0];
  return best.score > 0 ? best.i : null;
}


// ─── FORMAT KZ RESORT PACKAGES ─────────────────────────────────────────
