// ─── EXTRACT (مُصلح — city مستقل عن dest) ────────────────
function extract(text, hist) {
  const t = text || '';
  const e = {};

  // Destination (else-if chain)
  if (/كازاخستان|قازاقستان|kazakhstan/i.test(t)) e.dest = 'KZ';
  else if (/روسيا|russia/i.test(t)) e.dest = 'RU';
  else if (/بولندا|poland|وارسو|كراكوف/i.test(t)) e.dest = 'PL';
  else if (/أوزبكستان|اوزبكستان|uzbekistan|طشقند|سمرقند|بخارى/i.test(t)) e.dest = 'UZ';

  // City — مستقل عن الوجهة (FIX: كان else-if مع dest)
  if (/موسكو|moscow/i.test(t)) { if (!e.dest) e.dest = 'RU'; e.city = 'Moscow'; }
  if (/سان بطرسبرغ|سانت بطرسبرغ|petersburg/i.test(t)) { if (!e.dest) e.dest = 'RU'; e.city = 'Saint Petersburg'; }
  if (/^سانت$/i.test(t.trim())) { if (!e.dest) e.dest = 'RU'; e.needConfirmCity = true; }
  if (/ألماتي|الماتي|almaty/i.test(t)) { if (!e.dest) e.dest = 'KZ'; e.city = 'Almaty'; }
  if (/منتجع|أكواخ|اكواخ|ريزورت|resort|قاراغاي/i.test(t)) { e.resort = true; if (!e.dest) e.dest = 'KZ'; }

  // Multi-city — كل الصيغ
  if (/موسكو.*سانت|موسكو.*سان|سانت.*موسكو|سان.*موسكو|المدينتين|مدينتين|الاثنين|الثنتين|الاتنين|الكل|كلهم|both/i.test(t)) { e.multi = true; e.city = null; }

  // Nights
  const nightsM = t.match(/(\d+)\s*(?:ليالي|ليلة|ليله)/);
  if (nightsM) e.nights = parseInt(nightsM[1]);
  const daysM = t.match(/(\d+)\s*(?:أيام|ايام|يوم)/);
  if (daysM && !e.nights) e.nights = Math.max(parseInt(daysM[1]) - 1, 1);
  if (!e.nights && /اسبوعين|أسبوعين/i.test(t)) e.nights = 14;
  if (!e.nights && /اسبوع|أسبوع/i.test(t)) e.nights = 7;

  // Adults — text numbers (مع حماية من التقاط كلمات ضمن كلمات أطول مثل "كازاخستان" تحتوي "ست")
  const textNums = { واحد:1, شخصين:2, اثنين:2, ثلاثة:3, ثلاث:3, أربعة:4, أربع:4, خمسة:5, خمس:5, ستة:6, ست:6, سبعة:7, سبع:7, ثمانية:8, ثمان:8, تسعة:9, تسع:9, عشرة:10, عشر:10 };
  for (const [word, num] of Object.entries(textNums)) {
    // نتحقق أن الكلمة ليست مضمّنة في كلمة أطول (حروف عربية قبلها أو بعدها)
    if (new RegExp('(?<![\u0600-\u06FF])' + word + '(?![\u0600-\u06FF])', 'i').test(t)) { e.adults = num; break; }
  }
  // Adults — digit patterns
  if (!e.adults) {
    const am = t.match(/(\d+)\s*(?:أشخاص|اشخاص|شخص|بالغين|بالغ|أفراد|افراد|فرد|نفر)/);
    if (am) e.adults = parseInt(am[1]);
  }
  // Solo number after question — آخر رسالة ليلى فقط (وليس آخر N سطر)
  const _botMsgLines = (hist || '').split('\n').filter(l => l.startsWith('ليلى:'));
  const lastBot = _botMsgLines.slice(-1)[0] || '';
  if (!e.adults && /عدد البالغين|كم شخص|كم عدد/.test(lastBot)) {
    const solo = t.match(/^(\d{1,2})$/);
    if (solo && parseInt(solo[1]) >= 1 && parseInt(solo[1]) <= 15) e.adults = parseInt(solo[1]);
  }
  if (!e.nights && /كم ليلة|عدد الليالي/.test(lastBot)) {
    const solo = t.match(/^(\d{1,2})$/);
    if (solo && parseInt(solo[1]) >= 1 && parseInt(solo[1]) <= 30) e.nights = parseInt(solo[1]);
  }

  // Children
  const cm = t.match(/(\d+)\s*(?:أطفال|اطفال|طفل|طفلة|بزران|صغار|عيال)/);
  if (cm) e.kids_count = parseInt(cm[1]);
  if (/طفلين|طفلتين/i.test(t)) e.kids_count = 2;
  if (/طفل واحد|طفلة واحدة/i.test(t)) e.kids_count = 1;
  const ages = [];
  (t.match(/(\d+)\s*(?:سنة|سنوات|سن)/g) || []).forEach(s => {
    const n = parseInt(s); if (n > 0 && n < 18) ages.push(n);
  });
  if (!ages.length && /أعمار|عمر|الأطفال/.test(lastBot)) {
    t.split(/[و،,\s]+/).forEach(p => { const n = parseInt(p); if (n > 0 && n < 18) ages.push(n); });
  }
  if (ages.length) e.kids_ages = ages;

  // Multi-city nights: "6 موسكو 3 سانت" or "6 ليالي موسكو 3 سانت"
  const mcMatch = t.match(/(\d+)\s*(?:ليالي?\s+)?(?:في\s*)?(?:موسكو|moscow)/i);
  const mcMatch2 = t.match(/(\d+)\s*(?:ليالي?\s+)?(?:في\s*)?(?:سانت|سان بطرسبرغ|سانت بطرسبرغ|petersburg)/i);
  if (mcMatch) e.moscowNights = parseInt(mcMatch[1]);
  if (mcMatch2) e.spbNights = parseInt(mcMatch2[1]);

  // Currency request
  if (/بالريال\s*(السعودي)?|SAR/i.test(t)) e.currency = 'SAR';
  if (/بالدينار\s*(الكويتي)?|KWD/i.test(t)) e.currency = 'KWD';
  if (/بالريال العماني|OMR/i.test(t)) e.currency = 'OMR';
  if (/بالدرهم|AED/i.test(t)) e.currency = 'AED';
  if (/بالدينار البحريني|BHD/i.test(t)) e.currency = 'BHD';
  if (/بالريال القطري|QAR/i.test(t)) e.currency = 'QAR';
  if (/بالجنيه|EGP/i.test(t)) e.currency = 'EGP';

  // Limits
  if (e.nights && e.nights > 30) e.overLimit = 'nights';
  if (e.adults && e.adults > 15) e.overLimit = 'adults';

  return e;
}

// ─── INTENT ──────────────────────────────────────────────
function detectIntent(t) {
  t = (t || '').trim();
  if (/ضروري.*يرد|عاجل.*احجز|الرحلة.*بكرة.*ساعد|ضروري.*اتصل/i.test(t)) return 'urgent';
  if (/كلب|حمار|غبي|يلعن|تف/i.test(t)) return 'abuse';
  if (/احجز|نحجز|نثبت|ابي احجز|أبي أحجز|خلنا نحجز|نبي نحجز/i.test(t)) return 'book';
  if (/^(1|2|3|١|٢|٣)$/.test(t)) return 'select';
  if (/الاقتصادية|الفضية|الذهبية|الباقة الأولى|الباقه الاولى|الباقة الثانية|الباقة الثالثة/i.test(t)) return 'select';
  if (/غالي|سعر أقل|سعر اقل|اقل|أقل|ارخص|أرخص|اوفر|أوفر|مو مناسب|كثير|باهظ/i.test(t)) return 'cheaper';
  if (/بديل|غير|خيارات أخرى|خيارات اخرى|خيار ثاني|فنادق ثانية|خيارات|فيه غير/i.test(t)) return 'alt';
  if (/نقلل الجولات|نشيل الجولات|بدون جولات|باقة أساسية|باقه اساسيه|شيل الجولات|بدون سيارة|نقلل|تقليل/i.test(t)) return 'reduce';
  if (/برنامج|جدول|ايش بنزور|كم الجولات|كم جولة|المواقع|الأماكن/i.test(t)) return 'program';
  if (/صور الفندق|رابط الفندق|أبي أشوف الفندق/i.test(t)) return 'hotel_link';
  if (/فندق\s+\w|hotel\s+\w|ماريوت|هيلتون|ريتز|شيراتون/i.test(t)) return 'hotel_specific';
  if (/بالريال|بالدينار|بالدرهم|بالجنيه|SAR|KWD|OMR|AED|BHD|QAR|EGP/i.test(t)) return 'currency';
  if (/تأشيرة|فيزا|visa|تاشيره/i.test(t)) return 'visa';
  if (/الأفضل.*أو|أفضل.*ولا|مقارنة|الفرق بين/i.test(t)) return 'compare';
  if (/سعر الطفل|سعر الأطفال|السعر للشخص|السعر شامل/i.test(t)) return 'child_price';
  if (/لا شكرا|مو مهتم|ما أبي|ما اريد|ما ابي|لا أريد/i.test(t)) return 'decline';
  if (/^(تمام|طيب|ماشي|زين|اوكي|شكرا|مشكور|حلو|👍|🙏|ok)$/i.test(t)) return 'ack';
  if (/^(نعم|ايوه|أيوه|yes|sure|أكيد|بالتأكيد|اي|ايه)$/i.test(t)) return 'yes';
  if (/^(جديد|بداية جديدة|new)$/i.test(t)) return 'reset';
  if (/^(دائري|مفتوح|موسكو|سانت|لا)$/i.test(t)) return 'circular_answer';
  if (/^(مختص|فريق|تواصل|بشر)$/i.test(t)) return 'human';
  return 'other';
}

