// ─── SAVE QUOTE ──────────────────────────────────────────
async function saveQuote(ph, pkgs, dest, city, nights, adults) {
  const shown = pkgs.map(p => p.hotelName);
  const qd = JSON.stringify({ packages: pkgs.map(p => ({ tier: p.tier, tierAr: p.tierAr, hotelName: p.hotelName, totalUSD: p.totalUSD, stars: p.stars })), shown_hotels: shown, dest, city, nights, adults, timestamp: new Date().toISOString() });
  try { await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/leads?phone=eq.' + ph, headers: { ...sbH, Prefer: 'return=representation' }, body: { notes: qd } }); } catch (e) {}
}

