          prog += '📍 ' + routeStr2 + '\n';
          prog += '🗓 ' + (totalN2 + 1) + ' أيام / ' + totalN2 + ' ليالٍ\n━━━━━━━━━━━━━━━\n\n';
          let dayNum = 1;
          for (const d of mTourRows) {
            const lbl = d.type === 'arrival' ? 'موسكو — الوصول' : 'موسكو';
            prog += '🗓️ *اليوم ' + dayNum++ + ' — ' + lbl + ':*\n' + d.description_ar + '\n\n';
          }
          if (sArrival) prog += '🗓️ *اليوم ' + dayNum++ + ' — الانتقال إلى سانت بطرسبرغ:*\n' + sArrival.description_ar + '\n\n';
          for (const d of sTourRows) prog += '🗓️ *اليوم ' + dayNum++ + ' — سانت بطرسبرغ:*\n' + d.description_ar + '\n\n';
          if (sDep) prog += '🗓️ *اليوم ' + dayNum + ' — ' + sDep.title_ar + ':*\n' + sDep.description_ar + '\n\n';
          prog += '📌 *ملاحظة:* هذا البرنامج مبدئي للتوضيح فقط.\nالترتيب النهائي والتفاصيل اليومية ستُنسَّق مع مختصنا السياحي بعد تأكيد الحجز 😊';
          await updateLead.call(this, phone, { stage: 'interested' });
          return reply(prog);
        }
      }

      // ─── مدينة واحدة ────────────────────────────────────────────────
      const pd = dest === 'KZ' ? 'Kazakhstan' : 'Russia';
      const cityFilter = (dest === 'RU' && city && city !== 'multi') ? '&city=eq.' + encodeURIComponent(city) : (dest === 'KZ' ? '&city=eq.Almaty' : '');
      const bestN = [6, 9, 11].reduce((a, b) => Math.abs(a - (nights || 7)) < Math.abs(b - (nights || 7)) ? a : b);
      const rows = await this.helpers.httpRequest({ method: 'GET',
        url: SB + '/itineraries?country=eq.' + pd + cityFilter + '&notes_ar=eq.nights%3A' + bestN + '&order=day_number.asc',
        headers: { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY } });
      if (rows && rows.length) {
        const destLabel = city === 'Moscow' ? 'موسكو' : city === 'Saint Petersburg' ? 'سانت بطرسبرغ' : (DESTS[dest]?.name || dest);
        let prog = '📋 *البرنامج السياحي — ' + destLabel + '*\n\n';
        for (const d of rows) prog += '🗓️ *اليوم ' + d.day_number + ':*\n' + d.description_ar + '\n\n';
        prog += '📌 *ملاحظة:* هذا البرنامج مبدئي للتوضيح فقط.\nالترتيب النهائي ستُنسَّق مع مختصنا السياحي بعد تأكيد الحجز 😊';
        await updateLead.call(this, phone, { stage: 'interested' });
        return reply(prog);
      }
    } catch (e) { console.error('[program]', e.message); }
    return reply('البرنامج التفصيلي بنرسله مع تأكيد الحجز 😊\n\n💡 أرسلوا رقم الباقة: 1 أو 2 أو 3');
  }
  // HOTEL LINK
  if (it === 'hotel_link') {
    const lp = lastQuote.packages || [];
    if (lp.length) {
      let links = '';
      for (const p of lp) { const gq = encodeURIComponent(p.hotelName + ' hotel'); links += '🏨 ' + p.hotelName + '\n🔗 google.com/search?q=' + gq + '\n\n'; }
      return reply('تفضلوا روابط الفنادق:\n\n' + links);
    }
    return reply('بخصوص استفساركم عن صور الفندق — تواصلوا مع فريقنا:\n👆 اضغطوا هنا: ' + SUPPORT);
  }

  // CURRENCY
  if (it === 'currency' && ex.currency) {
    const rate = await getExRate.call(this, ex.currency);
    if (rate && lastQuote.packages && lastQuote.packages.length) {
      const labels = { SAR:'ر.س', KWD:'د.ك', OMR:'ر.ع', AED:'د.إ', BHD:'د.ب', QAR:'ر.ق', EGP:'ج.م' };
      let resp = '';
      for (const p of lastQuote.packages) { const cv = Math.round(p.totalUSD * rate); resp += (p.tierAr || p.tier) + ': *' + cv.toLocaleString() + ' ' + (labels[ex.currency] || ex.currency) + '*\n'; }
      resp += '\n(السعر بالدولار هو المرجع الرسمي) 💱';
      return reply(resp);
    }
  }

  if (it === 'visa') return reply('🗺️ معلومات التأشيرة:\n🇰🇿 كازاخستان: بدون تأشيرة لدول الخليج\n🇷🇺 روسيا: بدون تأشيرة لدول الخليج\n🇺🇿 أوزبكستان: بدون تأشيرة لدول الخليج\n🇵🇱 بولندا: تحتاج شنغن\n\nللتفاصيل تواصلوا مع فريقنا 📞');
  if (it === 'compare') return reply('كل وجهة لها مميزاتها 😊\n🇰🇿 كازاخستان: طبيعة خلابة + أسعار ممتازة\n🇷🇺 روسيا: ثقافة غنية + معالم تاريخية\n\nأي وجهة تميلون لها عشان أعرض لكم الأسعار؟');
  if (it === 'child_price') return reply('الأسعار المعروضة للباقة كاملة (كل المجموعة) 😊\n\nسعر الأطفال يعتمد على العمر وسياسة الفندق.\nعطوني الأعمار بالضبط وأحسب لكم.');
  if (it === 'hotel_specific') return reply('بخصوص استفساركم عن هذا الفندق — تواصلوا مع فريقنا المختص:\n👆 اضغطوا هنا: ' + SUPPORT);

  if (it === 'decline') {
    await updateLead.call(this, phone, { stage: 'lost' });
    return reply('شكراً لتواصلكم! 🙏\nإذا غيّرتوا رأيكم أو تبون باقة مختلفة، أنا هنا دائماً.\n\n🌐 arcadia-tour.com');
  }

  if (it === 'ack' || it === 'yes') {
    return reply('عطوني رقم الباقة اللي عجبتكم:\n🥉 1 — الاقتصادية\n🥈 2 — الفضية\n🥇 3 — الذهبية\n\nأو قولوا لي إذا تبون خيار أرخص أو تفاصيل أكثر 😊\n\n💡 أرسلوا: 1 أو 2 أو 3');
  }

  // OTHER — سؤال غير مفهوم بعد العرض
  return reply('بخصوص استفساركم "' + msg.substring(0, 50) + '" — تواصلوا مع فريقنا المختص:\n👆 اضغطوا هنا: ' + SUPPORT + '\n\nأو أرسلوا رقم الباقة: 1 أو 2 أو 3');
}

// ═══ COLLECTING ═══════════════════════════════════════════

if (it === 'visa') return reply('🗺️ معلومات التأشيرة:\n🇰🇿 كازاخستان: بدون تأشيرة لدول الخليج\n🇷🇺 روسيا: بدون تأشيرة لدول الخليج\n🇺🇿 أوزبكستان: بدون تأشيرة لدول الخليج\n🇵🇱 بولندا: تحتاج شنغن\n\nللتفاصيل تواصلوا مع فريقنا 📞');
if (it === 'compare') return reply('كل وجهة لها مميزاتها 😊\n🇰🇿 كازاخستان: طبيعة خلابة + أسعار ممتازة\n🇷🇺 روسيا: ثقافة غنية + معالم تاريخية\n\nأي وجهة تميلون لها عشان أعرض لكم الأسعار؟');

// No destination
if (!dest) return reply('وين تحبون تسافرون؟ 😊\n\n🇰🇿 كازاخستان\n🇷🇺 روسيا\n🇵🇱 بولندا\n🇺🇿 أوزبكستان\n\n💡 أرسلوا اسم الوجهة');

// Russia needs city
if (dest === 'RU' && !city && !multi) {
  await updateLead.call(this, phone, { destination: 'RU', stage: 'collecting', pax_adults: adults, travel_dates: nights ? String(nights) : null });
  return reply('تفضلون موسكو، سان بطرسبرغ، أو المدينتين مع بعض؟ 😊\n\n💡 أرسلوا: موسكو / سانت / مدينتين');
}

// KZ + resort
// resort: اقرأ من sales_state فقط لو في جلسة نشطة (destination محدد في DB)
if (!ex.resort && lead.destination) {
  let _ssTmpR = null;
  try { _ssTmpR = JSON.parse(lead.sales_state || 'null'); } catch(e) {}
  if (_ssTmpR?.resort) ex.resort = true;
}

// ═══ KZ RESORT FLOW ══════════════════════════════════════════════════════
if (dest === 'KZ' && ex.resort && adults && nights) {

  // ── حالة البوت الحالية ──────────────────────────────────────────────────
  const _rAllBotLines = chatHistory.split('\n').filter(l => l.startsWith('ليلى:'));
  const _rLastBotL    = _rAllBotLines.slice(-1)[0] || '';
  const _rLastIsResortQ = /كم ليلة.*منتجع|كم ليلة.*أكواخ/i.test(_rLastBotL);
  const _rLastIsRoomQ   = /كيف تفضلون توزيع الغرف/.test(_rLastBotL);

  // ── اقرأ الحالة المحفوظة ────────────────────────────────────────────────
  let _rState = null;
  try { _rState = JSON.parse(lead.sales_state || 'null'); } catch(e) {}

  // ── استخرج resortNights: DB → تاريخ → رسالة حالية ──────────────────────
  let _resortN = _rState?.resortNights || null;

  if (!_resortN) {
    // 1. من تاريخ المحادثة: بحث عن سؤال resort ثم إجابة العميل التالية
    const _rHLines = chatHistory.split('\n');
    for (let _rhi = 0; _rhi < _rHLines.length - 1; _rhi++) {
      if (_rHLines[_rhi].startsWith('ليلى:') && /كم ليلة.*منتجع|كم ليلة.*أكواخ/i.test(_rHLines[_rhi])) {
        for (let _rhj = _rhi + 1; _rhj < _rHLines.length; _rhj++) {
          if (_rHLines[_rhj].startsWith('العميل:')) {
            const _rhm = _rHLines[_rhj].match(/العميل:\s*(\d{1,2})\s*$/);
            if (_rhm) { _resortN = Math.min(parseInt(_rhm[1]), nights); }
            break;
          }
        }
        if (_resortN) break;
      }
    }
  }

  if (!_resortN && _rLastIsResortQ) {
    // 2. الرسالة الحالية هي إجابة سؤال resort
    const _rCurM = msg.match(/^(\d{1,2})$/);
    if (_rCurM) _resortN = Math.min(parseInt(_rCurM[1]), nights);
    if (!_resortN && /كلها?|كل|كامل|جميع/.test(msg)) _resortN = nights;
  }

  if (!_resortN) {
    // اسأل كم ليلة في المنتجع
    let _rSS = { ...(_rState || {}), resort: true, city: 'Almaty Region' };
    await updateLead.call(this, phone, {
      destination: 'KZ', stage: 'collecting',
      pax_adults: adults, travel_dates: String(nights),
      sales_state: JSON.stringify(_rSS)
    });
    return reply(
      'كم ليلة ودّون تقضونها في المنتجع/الأكواخ؟ 🌲\n\n' +
      (nights > 1 ? '(باقي الليالي ستكون في الماتي المدينة — إجمالي ' + nights + ' ليالٍ)\n\n' : '') +
      '💡 أرسلوا رقم، أو "كلها" لو الرحلة كلها في المنتجع'
    );
  }

  // ── segments ─────────────────────────────────────────────────────────────
  const _rCityN = nights - _resortN;
  const _rSegs  = [];
  if (_rCityN > 0) _rSegs.push({ city: 'Almaty', nights: _rCityN });
  _rSegs.push({ city: 'Almaty Region', nights: _resortN, tours: 0 });

  // ── اختيار الغرف ─────────────────────────────────────────────────────────
  const _rRoomOpts = getRoomOptions(adults, kids_count);

  // استرجع غرفة محفوظة (تحقق من تطابق عدد الأشخاص)
  let _rSelRoom = null;
  if (_rState?.selectedRoom?.config?.rooms) {
    const _rOcc = _rState.selectedRoom.config.rooms.reduce(
      (s, r) => s + (r.occ === 'SGL' ? 1 : r.occ === 'DBL' ? 2 : 3) * r.count, 0
    );
    if (_rOcc === adults + kids_count) _rSelRoom = _rState.selectedRoom;
  }

  if (_rRoomOpts && !_rSelRoom) {
    if (_rLastIsRoomQ) {
      // الرسالة الحالية هي إجابة سؤال الغرف
      const _rIdx = matchRoomByDesc(msg.trim(), _rRoomOpts);
      if (_rIdx !== null) {
        const _rChosen = _rRoomOpts[_rIdx];
        // احفظ الغرفة + resort nights
        await updateLead.call(this, phone, {
          destination: 'KZ', stage: 'collecting', pax_adults: adults, travel_dates: String(nights),
          sales_state: JSON.stringify({ ...(_rState || {}), resort: true, resortNights: _resortN,
            selectedRoom: { config: _rChosen.config, display: _rChosen.display } })
        });
        const _rPE = await callPE.call(this, {
          destination: 'KZ', segments: _rSegs, adults,
          childrenAges: kids_ages, clientType: 'B2C', roomConfig: _rChosen.config
        });
        if (_rPE.ok && _rPE.packages?.length) {
          const _rTxt = await fmtKZResortPkgs.call(this, _rPE.packages, nights, adults, kids_count, _rChosen.display);
          await updateLead.call(this, phone, { stage: 'quoted', offer_sent: true,
            offer_amount_usd: _rPE.packages[0].totalUSD,
            last_quote_at: new Date().toISOString(),
            next_followup: new Date(Date.now() + 3 * 3600000).toISOString(), paused: false });
          await saveQuote.call(this, phone, _rPE.packages, 'KZ', 'Almaty Region', nights, adults);
          return reply(_rTxt);
        }
        return reply('عذراً، ما قدرت أجيب أسعار 😊\n\nتواصلوا مع فريقنا:\n👆 اضغطوا هنا: ' + SUPPORT);
      }
      // إدخال غير صالح
      return reply('من فضلكم أرسلوا 1 أو 2');
    }

    // اسأل عن الغرف
    let _rRoomQ = '🛏 كيف تفضلون توزيع الغرف؟\n\n';
    for (const o of _rRoomOpts) _rRoomQ += o.label + '\n';
    _rRoomQ += '\n💡 أرسلوا: 1 أو 2';
    await updateLead.call(this, phone, {
      destination: 'KZ', stage: 'collecting', pax_adults: adults, travel_dates: String(nights),
      sales_state: JSON.stringify({ ...(_rState || {}), resort: true, resortNights: _resortN,
        roomChoices: _rRoomOpts.map(o => ({ label: o.label, config: o.config, display: o.display })) })
    });
    return reply(_rRoomQ);
  }

  // ── استدعاء PE مباشرة (2 أشخاص أو غرفة محفوظة) ─────────────────────────
  const _rFinalRoomCfg = _rSelRoom?.config || null;
  const _rFinalDisplay = _rSelRoom?.display || calcRooms(adults, kids_count);
  const _rPE2 = await callPE.call(this, {
    destination: 'KZ', segments: _rSegs, adults,
    childrenAges: kids_ages, clientType: 'B2C', roomConfig: _rFinalRoomCfg
  });
  if (_rPE2.ok && _rPE2.packages?.length) {
    const _rTxt2 = await fmtKZResortPkgs.call(this, _rPE2.packages, nights, adults, kids_count, _rFinalDisplay);
    await updateLead.call(this, phone, { stage: 'quoted', offer_sent: true,
      offer_amount_usd: _rPE2.packages[0].totalUSD,
      last_quote_at: new Date().toISOString(),
      next_followup: new Date(Date.now() + 3 * 3600000).toISOString(), paused: false });
    await saveQuote.call(this, phone, _rPE2.packages, 'KZ', 'Almaty Region', nights, adults);
    return reply(_rTxt2);
  }
  return reply('عذراً، ما قدرت أجيب أسعار 😊\n\nتواصلوا مع فريقنا:\n👆 اضغطوا هنا: ' + SUPPORT);
}
// ═══════════════════════════════════════════════════════════════════════════


// Multi-city
if (multi && dest === 'RU') {
  // ── أولاً: استرجع mN/sN من sales_state — فقط لو يتطابق مع الليالي الحالية
  let _savedState = null;
  try { _savedState = JSON.parse(lead.sales_state || 'null'); } catch(e) {}
  const _savedMN = _savedState?.moscowNights || null;
  const _savedSN = _savedState?.spbNights || null;
  const _savedTotal = (_savedMN && _savedSN) ? (_savedMN + _savedSN) : null;
  // لا نثق بالـ saved state إذا كان مجموع الليالي المحفوظ يختلف عن الليالي المطلوبة حالياً
  const _savedNightsValid = !nights || !_savedTotal || (_savedTotal === nights);
  let mN = (_savedNightsValid && _savedMN) ? _savedMN : (ex.moscowNights || null);
  let sN = (_savedNightsValid && _savedSN) ? _savedSN : (ex.spbNights || null);

  // ── ثانياً: استخرج من الرسالة الحالية
  if (!mN) { const mm = msg.match(/(\d+)\s*(?:ليالي?\s*)?(?:في\s*)?(?:موسكو|moscow)/i); if (mm) mN = parseInt(mm[1]); }
  if (!mN) { const mm = msg.match(/(?:موسكو|moscow)\s*(\d+)/i); if (mm) mN = parseInt(mm[1]); }
  if (!sN) { const sm = msg.match(/(\d+)\s*(?:ليالي?\s*)?(?:في\s*)?(?:سانت|سان بطرسبرغ|سانت بطرسبرغ|petersburg)/i); if (sm) sN = parseInt(sm[1]); }
  if (!sN) { const sm = msg.match(/(?:سانت|سان بطرسبرغ|petersburg)\s*(\d+)/i); if (sm) sN = parseInt(sm[1]); }

  // "5 و 3" — أرقام بالترتيب (موسكو أول) — من الرسالة الحالية
  const lastBotMsg = (chatHistory.match(/ليلى:[^\n]+/g) || []).slice(-1)[0] || '';
  if (!mN && !sN) {
    const nums = msg.match(/(\d+)\s*(?:و|,|\s)\s*(\d+)/);
    if (nums) { mN = parseInt(nums[1]); sN = parseInt(nums[2]); }
  }

  // ── ثالثاً: ابحث في رسائل العميل فقط (تجنب التقاط أمثلة ليلى كـ "4 موسكو 3 سانت")
  const _userMsgs = chatHistory.split('\n').filter(l => l.startsWith('العميل:')).join('\n');
  if (!mN) { const hm = _userMsgs.match(/(\d+)\s*(?:ليالي?\s*)?(?:في\s*)?(?:موسكو|moscow)/i); if (hm) mN = parseInt(hm[1]); }
  if (!sN) { const hs = _userMsgs.match(/(\d+)\s*(?:ليالي?\s*)?(?:في\s*)?(?:سانت|سان|petersburg)/i); if (hs) sN = parseInt(hs[1]); }
  // "5 و 3" في تاريخ العميل
  if (!mN && !sN) {
    const huNums = _userMsgs.match(/(\d+)\s*(?:و|,)\s*(\d+)/);
    if (huNums) { mN = parseInt(huNums[1]); sN = parseInt(huNums[2]); }
  }

  // رقم منفرد بعد سؤال عن مدينة محددة
  if (!sN && /سان بطرسبرغ/.test(lastBotMsg)) { const solo = msg.match(/^(\d{1,2})$/); if (solo) sN = parseInt(solo[1]); }
  if (!mN && /موسكو/.test(lastBotMsg)) { const solo = msg.match(/^(\d{1,2})$/); if (solo) mN = parseInt(solo[1]); }

  if (!mN && !sN) { await updateLead.call(this, phone, { destination: 'RU', stage: 'collecting', pax_adults: adults, travel_dates: nights ? String(nights) : null }); return reply('كم ليلة في كل مدينة؟ 😊\n\n💡 أمثلة:\n• 4 موسكو 3 سانت\n• أو: 4 و 3'); }
  if (mN && !sN) { await updateLead.call(this, phone, { destination: 'RU', stage: 'collecting' }); return reply('وكم ليلة في سان بطرسبرغ؟ 😊\n\n💡 أرسلوا رقم مثل: 3'); }
  if (!mN && sN) { await updateLead.call(this, phone, { destination: 'RU', stage: 'collecting' }); return reply('وكم ليلة في موسكو؟ 😊\n\n💡 أرسلوا رقم مثل: 4'); }

  const totalN = mN + sN;

  if (!adults) {
    await updateLead.call(this, phone, { destination: dest, travel_dates: String(totalN) });
    return reply('كم عدد البالغين؟ 👥\n\n💡 أرسلوا رقم مثل: 2');
  }

  // Circular question
  const askedCircular = /الوصول والمغادرة|دائرية/.test(chatHistory);
  const answeredCircular = /دائري|مفتوح/.test(chatHistory) || /^(نعم|لا|دائري|مفتوح|موسكو|سانت)$/i.test(msg.trim());

  if (!askedCircular && !answeredCircular) {
    await updateLead.call(this, phone, { destination: 'RU', stage: 'collecting', sales_state: JSON.stringify({ moscowNights: mN, spbNights: sN }) });
    return reply('الوصول والمغادرة من موسكو (رحلة دائرية 🔄)؟\nأم المغادرة من سان بطرسبرغ؟\n\n💡 أرسلوا: دائري / مفتوح');
  }

  // isCircular: 1) من saved state (الأكثر موثوقية)
  //             2) من تاريخ المحادثة (بحث بوت سأل → إجابة العميل)
  //             3) من الرسالة الحالية فقط لو البوت سأل سؤال الدائري
  let isCircular;
  if (_savedState?.isCircular !== undefined && _savedState?.isCircular !== null) {
    isCircular = _savedState.isCircular;
  } else {
    isCircular = true; // افتراضي
    const _circLastIsQ = /الوصول والمغادرة|دائرية/.test(lastBotMsg);
    if (_circLastIsQ) {
      // الرسالة الحالية هي إجابة سؤال الدائري → استخدمها
